import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MOD = 1000000007;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        int p;
        if (k < 2) {
            p = n - (1 - k);
        } else {
            int t = 1;
            int a = k;
            while (a != 1) {
                a = (int)((long)a * k % n);
                t++;
            }
            p = (n - 1) / t;
        }
        System.out.println(pow(n, p, MOD));
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
